corrected_code:
router.post('/warehouse/inventory/relocate', authenticateSupplier, async (ctx) => {
  const { palletId, targetAisle, targetRack } = ctx.request.body;

  const client = await pgPool.connect();
  try {
    const res = await client.query(
      'UPDATE warehouse_pallets SET aisle_id = $1, rack_id = $2, moved_at = NOW() WHERE pallet_id = $3 AND supplier_id = $4 RETURNING *',
      [targetAisle, targetRack, palletId, ctx.state.supplier.id]
    );
    if (res.rowCount === 0) {
      ctx.status = 403;
      ctx.body = { error: 'Access denied: pallet does not belong to your supplier account' };
      return;
    }
    ctx.body = { success: true, pallet: res.rows[0] };
  } finally {
    client.release();
  }
});
